<?php $map=array_column($series,null,'nome'); $maxValue=max([1,...array_map(fn($r)=>max((int)$r['receitas'],(int)$r['despesas']),$series)]); ?>
<div class="chart-legend"><span class="legend-income">Receitas</span><span class="legend-expense">Despesas</span></div>
<div class="month-chart" role="img" aria-label="Comparação mensal de receitas e despesas; valores na tabela abaixo">
<?php for($i=-5;$i<=0;$i++): $m=\App\Core\FinancialDate::shift($month,$i); $row=$map[$m] ?? ['receitas'=>0,'despesas'=>0]; ?><div class="chart-month"><div class="chart-columns"><div class="chart-bar income" style="height:<?= max(2,round(max(0,(int)$row['receitas'])/$maxValue*100)) ?>%" title="Receitas: <?= Money::format((int)$row['receitas']) ?>"></div><div class="chart-bar expense" style="height:<?= max(2,round(max(0,(int)$row['despesas'])/$maxValue*100)) ?>%" title="Despesas: <?= Money::format((int)$row['despesas']) ?>"></div></div><span><?= H::escape(substr($m,5,2).'/'.substr($m,2,2)) ?></span></div><?php endfor; ?></div>
