</div></section><section class="card"><div class="card-body"><div class="section-heading"><h2 class="h4">Próximos compromissos</h2><a href="<?= H::escape($basePath.'/recorrencias') ?>">Recorrências →</a></div><?php if (!$upcoming): ?><p class="empty-state">Nenhuma pendência cadastrada. Seus próximos vencimentos aparecerão aqui.</p><?php endif; ?><?php foreach($upcoming as $t): ?><a class="list-row text-decoration-none" href="<?= H::escape($basePath.'/movimentacoes/'.$t['id']) ?>"><div><?= H::escape($t['descricao']) ?><small class="d-block <?= $t['data_vencimento']<date('Y-m-d') ? 'text-danger' : 'text-secondary' ?>"><?= H::date($t['data_vencimento']) ?> · <?= $t['data_vencimento']<date('Y-m-d') ? 'Atrasado' : ($t['tipo']==='receita' ? 'A receber' : 'A pagar') ?></small></div><strong><?= Money::format((int)$t['valor_centavos']) ?></strong></a><?php endforeach; ?></div></section></div>
<div class="col-xl-4"><section class="card mb-4"><div class="card-body"><div class="section-heading"><h2 class="h4">Seus cartões</h2><a href="<?= H::escape($basePath.'/cartoes') ?>">Ver todos</a></div><?php $unpaid=array_values(array_filter($invoices,fn($f)=>(int)$f['total']>(int)$f['pago'])); usort($unpaid,fn($a,$b)=>strcmp($a['data_vencimento'],$b['data_vencimento'])); ?><?php if (!$unpaid): ?><p class="text-secondary py-3">Nenhuma fatura a pagar.</p><?php endif; ?><?php foreach(array_slice($unpaid,0,4) as $f): ?><a class="list-row text-decoration-none" href="<?= H::escape($basePath.'/faturas/'.$f['id']) ?>"><div><?= H::escape($f['cartao_nome']) ?><small class="d-block text-secondary">Vence <?= H::date($f['data_vencimento']) ?></small></div><strong><?= Money::format((int)$f['total']-(int)$f['pago']) ?></strong></a><?php endforeach; ?></div></section>
<section class="card mb-4"><div class="card-body"><div class="section-heading"><h2 class="h4">Orçamento do mês</h2><a href="<?= H::escape($basePath.'/planejamento?mes='.$month) ?>">Planejar</a></div><?php if (!$budgets): ?><p class="text-secondary py-3">Defina seus primeiros limites por categoria.</p><?php endif; ?><?php foreach(array_slice($budgets,0,4) as $b): ?><div class="py-3"><div class="d-flex justify-content-between small mb-2"><strong><?= H::escape($b['nome']) ?></strong><span><?= round((int)$b['realizado']/(int)$b['valor_limite_centavos']*100) ?>%</span></div><progress class="uai-progress" max="<?= (int)$b['valor_limite_centavos'] ?>" value="<?= min(max(0,(int)$b['realizado']),(int)$b['valor_limite_centavos']) ?>" aria-label="Consumo de <?= H::escape($b['nome']) ?>"></progress><small class="text-secondary">Restante: <?= Money::format((int)$b['valor_limite_centavos']-(int)$b['realizado']) ?></small></div><?php endforeach; ?></div></section>
<section class="card"><div class="card-body"><h2 class="h4">Resultado do mês</h2><strong class="metric-value"><?= Money::format((int)$totals['receitas']-(int)$totals['despesas']) ?></strong><p class="small text-secondary mt-2 mb-0">Pendentes: <?= Money::format((int)$totals['receber']) ?> a receber e <?= Money::format((int)$totals['pagar']) ?> a pagar, por competência.</p></div></section></div></div>
